{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Tetrabenazine, the closest analogue (Morgan 0.3731), has very low absolute oral bioavailability in patients (mean 4.9 ± 3.2%), indicating extensive first-pass metabolism; the query shares the dimethoxy-substituted fused bicyclic core and a cyclic carbonyl, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Almorexant, a dimethoxy-tetrahydroisoquinoline amide with a basic amine and aromatic substituent, has absolute oral bioavailability of 11.2% in healthy subjects, supporting low F for the query's amide/amine/dimethoxyaryl scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Donepezil, a dimethoxyaryl basic amine, has ~100% oral bioavailability in humans, providing a high-F counterexample; however, its lower similarity and smaller size limit transfer to the larger amide-containing query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C21"],
      "claim": "Valbenazine, a tetrabenazine prodrug, has ~49% absolute oral bioavailability, but this high F depends on ester prodrug hydrolysis, a mechanism not present in the query's amide-linked structure.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C35"],
      "claim": "Verapamil, a dimethoxyphenyl tertiary amine, has absolute oral bioavailability of 22.0% in normal subjects, slightly above the threshold; this is a weak contradictory signal because the query is larger and contains an amide lactam.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Low predicted. The most transferable direct measurements (tetrabenazine ~5%, almorexant ~11%) indicate low oral bioavailability for the query's dimethoxyaryl amide/amine scaffold. High-F analogues are less similar or depend on prodrug mechanisms absent in the query; verapamil is borderline and does not outweigh the low-F anchors.",
  "evidence_gaps": [
    "No direct experimental F measurement for the query molecule.",
    "Morgan similarities are low (0.25-0.37), limiting transferability.",
    "No data on permeability, efflux, or metabolic stability of the query.",
    "Verapamil borderline F makes the threshold decision sensitive."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

